  <!-- JAVASCRIPT VAINILLA (INTERACCIONES) -->
  <!-- ========================================================================= -->
  <script>
    document.addEventListener('DOMContentLoaded', () => {

      // 1. Menú Móvil
      const mobileMenuBtn = document.getElementById('mobile-menu-btn');
      const mobileMenu = document.getElementById('mobile-menu');
      const hamburgerIcon = document.getElementById('hamburger-icon');
      const closeIcon = document.getElementById('close-icon');
      const mobileNavLinks = document.querySelectorAll('.mobile-nav-link');

      const toggleMenu = () => {
        const isHidden = mobileMenu.classList.contains('hidden');
        if (isHidden) {
          mobileMenu.classList.remove('hidden');
          hamburgerIcon.classList.add('hidden');
          closeIcon.classList.remove('hidden');
        } else {
          mobileMenu.classList.add('hidden');
          hamburgerIcon.classList.remove('hidden');
          closeIcon.classList.add('hidden');
        }
      };

      if (mobileMenuBtn) {
        mobileMenuBtn.addEventListener('click', toggleMenu);
      }

      mobileNavLinks.forEach(link => {
        link.addEventListener('click', () => {
          if (!mobileMenu.classList.contains('hidden')) {
            toggleMenu();
          }
        });
      });

      // 2. Acordeones de Tarifas
      const accordionItems = document.querySelectorAll('.accordion-item');

      accordionItems.forEach(item => {
        const trigger = item.querySelector('.accordion-trigger');

        trigger.addEventListener('click', () => {
          const isActive = item.classList.contains('active');

          accordionItems.forEach(otherItem => {
            if (otherItem !== item) {
              otherItem.classList.remove('active');
              otherItem.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
            }
          });

          if (isActive) {
            item.classList.remove('active');
            trigger.setAttribute('aria-expanded', 'false');
          } else {
            item.classList.add('active');
            trigger.setAttribute('aria-expanded', 'true');
          }
        });
      });

      // 3. Animaciones de Scroll (Intersection Observer)
      const revealItems = document.querySelectorAll('.reveal-item');

      if ('IntersectionObserver' in window) {
        const observerOptions = {
          root: null,
          rootMargin: '0px 0px -60px 0px',
          threshold: 0.1
        };

        const revealObserver = new IntersectionObserver((entries, observer) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              entry.target.classList.add('is-revealed');
              observer.unobserve(entry.target);
            }
          });
        }, observerOptions);

        revealItems.forEach(el => revealObserver.observe(el));
      } else {
        revealItems.forEach(el => el.classList.add('is-revealed'));
      }

      // 4. Modales Legales
      const legalModal = document.getElementById('legal-modal');
      const modalContent = document.getElementById('modal-content');
      const closeModalBtn = document.getElementById('close-modal-btn');
      const modalTriggers = document.querySelectorAll('.legal-modal-trigger');

      const legalTexts = {
        'aviso-legal': `
          <div class="font-mono text-xs text-[#FF3B00] uppercase mb-2">[ TEXTO LEGAL VIGENTE ]</div>
          <h3 class="font-title text-2xl font-bold text-[#EAECEF] mb-4">Aviso Legal</h3>
          <p>En cumplimiento de la legislación aplicable en materia de servicios de la sociedad de la información y de comercio electrónico, se informa que este sitio web y los servicios de taller técnico oficial son operados por:</p>
          <ul class="list-disc pl-5 space-y-1 font-mono text-xs text-[#EAECEF]/80 my-3">
            <li><strong>Razón Social:</strong> Atlantia Scuba Experience S.L.</li>
            <li><strong>Denominación comercial:</strong> O₂ TECH / Atlantia Dive Center</li>
            <li><strong>Domicilio Social:</strong> C/ Italia, 2, 28916 Leganés (Madrid)</li>
            <li><strong>Email de contacto:</strong> taller@atlantiadive.com</li>
            <li><strong>Teléfono de atención:</strong> +34 600 000 000</li>
          </ul>
          <p class="text-xs text-[#EAECEF]/60">Las marcas Mares, Aqualung, Apeks y Christolube mencionadas son propiedad de sus respectivos fabricantes y se citan en calidad de acreditación técnica de servicio autorizado y compatibilidad de repuestos.</p>
        `,
        'politica-privacidad': `
          <div class="font-mono text-xs text-[#FF3B00] uppercase mb-2">[ SEGURIDAD & PRIVACIDAD ]</div>
          <h3 class="font-title text-2xl font-bold text-[#EAECEF] mb-4">Política de Privacidad</h3>
          <p>Atlantia Scuba Experience S.L. garantiza la confidencialidad de los datos personales facilitados a través de las solicitudes de presupuesto por correo electrónico o recepción en taller.</p>
          <p>Tus datos únicamente se utilizarán para la gestión del servicio técnico, elaboración de presupuestos, comunicación del estado de calibración y facturación conforme a las normativas de la UE (RGPD).</p>
          <p class="text-xs text-[#EAECEF]/60 pt-2">Puedes ejercer tus derechos de acceso, rectificación, supresión y limitación de datos contactando directamente en taller@atlantiadive.com.</p>
        `
      };

      modalTriggers.forEach(btn => {
        btn.addEventListener('click', () => {
          const type = btn.getAttribute('data-modal');
          if (legalTexts[type]) {
            modalContent.innerHTML = legalTexts[type];
            legalModal.classList.remove('hidden');
            legalModal.classList.add('flex');
            document.body.style.overflow = 'hidden';
          }
        });
      });

      const closeModal = () => {
        legalModal.classList.add('hidden');
        legalModal.classList.remove('flex');
        document.body.style.overflow = '';
      };

      if (closeModalBtn) closeModalBtn.addEventListener('click', closeModal);
      legalModal.addEventListener('click', (e) => {
        if (e.target === legalModal) closeModal();
      });
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !legalModal.classList.contains('hidden')) {
          closeModal();
        }
      });

      // 5. Scroll Header Shadow
      const header = document.getElementById('site-header');
      window.addEventListener('scroll', () => {
        if (window.scrollY > 40) {
          header.classList.add('border-b', 'border-[#EAECEF]/15', 'shadow-2xl', 'shadow-black/50');
        } else {
          header.classList.remove('shadow-2xl', 'shadow-black/50');
        }
      });

    });
  </script>

